pub fn search(query: &str) -> Vec<&'static Icon> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    ICONS.iter().filter(|i| { let text=format!("{} {} {}",i.id,i.name,i.family).to_lowercase(); words.iter().all(|w|text.contains(w)) }).collect()
}
pub struct Atlas { textures: Vec<egui::TextureHandle> }
impl Atlas {
    pub fn load(ctx: &egui::Context) -> Result<Self,String> {
        let pages: &[&[u8]] = &[include_bytes!("atlas.png"),include_bytes!("atlas-1.png"),include_bytes!("atlas-2.png"),include_bytes!("atlas-3.png"),include_bytes!("atlas-4.png")];
        let mut textures=Vec::new();
        for (i,page) in pages.iter().enumerate() {
            let rgba=image::load_from_memory(page).map_err(|e|e.to_string())?.to_rgba8();
            let size=[rgba.width() as usize,rgba.height() as usize];
            let color=egui::ColorImage::from_rgba_unmultiplied(size,rgba.as_raw());
            textures.push(ctx.load_texture(format!("cse-engineering-components-{i}"),color,egui::TextureOptions::LINEAR));
        }
        Ok(Self { textures })
    }
    pub fn draw(&self,ui: &mut egui::Ui,id: &str,size:f32) -> Result<egui::Response,String> {
        let icon=ICONS.iter().find(|i|i.id==id).ok_or_else(||format!("Unknown CSE component: {id}"))?;
        let [l,t,r,b]=icon.uv;
        Ok(ui.add(egui::Image::new((self.textures[icon.atlas].id(),egui::Vec2::splat(size))).uv(egui::Rect::from_min_max(egui::pos2(l,t),egui::pos2(r,b)))).on_hover_text(format!("{} [{}]",icon.name,icon.id)))
    }
}
